SELECT T.DOMAIN_ID , T.COMPANY_CD , T.TASK_ID , T.TASK_NM , T.TASK_DETAIL , T.TASK_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM001', T.TASK_STATE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_STATE , T.TASK_START_DT , T.TASK_END_DT , SF_GET_CODE_NM('ko-KR', 'CM002', T.TASK_IMPORTANCE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_IMPORTANCE , T.TASK_OWNER_MEMBER_ID , T.TASK_PROGRESS , T.CHILD_TASK_ADD_YN , E.EMP_NM , TE.TASK_EMP_CD FROM TASK_MASTER T INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID) LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD)
T.DOMAIN_ID = #{domainId} AND TE.EMAIL = #{email}
AND T.TASK_STATE_CD = #{taskState}
AND TE.TASK_EMP_CD = #{taskEmpCd}
AND T.CHILD_TASK_ADD_YN = 'N'
AND (T.CHILD_TASK_ADD_YN = 'Y' OR T.CHILD_TASK_ADD_YN IS NULL)
AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
ORDER BY CASE WHEN T.TASK_END_DT is NULL THEN '2' WHEN T.TASK_END_DT = '' THEN '1' ELSE '0' END, TASK_STATE, T.TASK_END_DT, T.TASK_IMPORTANCE_CD LIMIT #{start}, #{length}

SELECT
    COUNT(*)
