        AND T.TASK_STATE_CD = #{taskState}



        AND T.TASK_NM LIKE CONCAT('%', #{taskNm}, '%')



        AND T.TASK_START_DT >= #{taskStartDt}



        AND T.TASK_END_DT  <= #{taskEndDt}

SELECT DISTINCT T.DOMAIN_ID , T.COMPANY_CD , T.TASK_ID , T.TASK_NM , T.TASK_DETAIL , T.TASK_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM001', T.TASK_STATE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_STATE , T.TASK_START_DT , T.TASK_END_DT , SF_GET_CODE_NM('ko-KR', 'CM002', T.TASK_IMPORTANCE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_IMPORTANCE , T.TASK_OWNER_MEMBER_ID , SF_GET_MEMBER_NAME(T.TASK_OWNER_MEMBER_ID) AS TASK_OWNER_MEMBER_NM , T.TASK_PROGRESS , T.CHILD_TASK_ADD_YN , T.TASK_TYPE_CD , SF_GET_CODE_NM('ko-KR', 'CM007', T.TASK_TYPE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_TYPE_NM , T.PARENT_TASK_ID , T.PROJECT_ID , '1' AS LEVEL FROM task_master T INNER JOIN PROJECT_EMP pe ON T.PROJECT_ID = pe.PROJECT_ID
T.PROJECT_ID = #{projectId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL) AND (T.TASK_TYPE_CD = 'CM007CD001' OR T.TASK_TYPE_CD = 'CM007CD002') AND (T.PARENT_TASK_ID IS NULL OR T.PARENT_TASK_ID = '') AND pe.EMAIL = #{email}
AND T.TASK_STATE_CD = #{taskState}
AND T.TASK_NM LIKE CONCAT('%', #{taskNm}, '%')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
ORDER BY CASE WHEN T.TASK_END_DT is NULL THEN '2' WHEN T.TASK_END_DT = '' THEN '1' ELSE '0' END, T.TASK_END_DT, T.TASK_NM
LIMIT #{start}, #{length}

SELECT DISTINCT T.DOMAIN_ID , T.COMPANY_CD , T.TASK_ID , T.TASK_NM , T.TASK_DETAIL , SF_GET_CODE_NM('ko-KR', 'CM001', T.TASK_STATE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_STATE , T.TASK_START_DT , T.TASK_END_DT , SF_GET_CODE_NM('ko-KR', 'CM002', T.TASK_IMPORTANCE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_IMPORTANCE , T.TASK_OWNER_MEMBER_ID , T.TASK_PROGRESS , T.CHILD_TASK_ADD_YN , T.TASK_TYPE_CD , SF_GET_CODE_NM('ko-KR', 'CM007', T.TASK_TYPE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_TYPE_NM , C.COMPANY_NM EMP_COMPANY_NM , E.EMP_NM , TE.TASK_EMP_CD , SF_GET_CODE_NM('ko-KR', 'CM004', TE.TASK_EMP_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_EMP , T.PARENT_TASK_ID FROM TASK_MASTER T INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID) LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) INNER JOIN COMPANY_MASTER C ON (C.DOMAIN_ID = E.DOMAIN_ID AND C.COMPANY_CD = E.COMPANY_CD) INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID) INNER JOIN EMP_MASTER E2 ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD) LEFT JOIN TASK_LABEL TL ON (TL.TASK_ID = T.TASK_ID AND TL.DOMAIN_ID = T.DOMAIN_ID)
T.DOMAIN_ID = #{domainId} AND TE.EMAIL = #{email} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
AND T.TASK_STATE_CD = #{taskState}
AND T.TASK_NM LIKE CONCAT('%', #{taskNm}, '%')
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
AND TE.TASK_EMP_CD = #{taskEmpCd}
AND T.CHILD_TASK_ADD_YN = 'N'
AND (T.CHILD_TASK_ADD_YN = 'Y' OR T.CHILD_TASK_ADD_YN IS NULL)
AND E2.EMP_NM LIKE REPLACE(CONCAT('%', #{taskEmpNm}, '%'), ' ','')
AND TL.LABEL_ID = #{labelId} AND TL.EMAIL = #{email}
AND T.TASK_ID NOT IN ( SELECT T.TASK_ID FROM TASK_MASTER T INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID) LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) WHERE T.DOMAIN_ID = #{domainId} AND TE.EMAIL = #{email} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL) AND T.PARENT_TASK_ID IN ( SELECT T.TASK_ID FROM TASK_MASTER T INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID) LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID) INNER JOIN EMP_MASTER E2 ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD) LEFT JOIN TASK_LABEL TL ON (TL.TASK_ID = T.TASK_ID AND TL.DOMAIN_ID = T.DOMAIN_ID) WHERE T.DOMAIN_ID = #{domainId} AND TE.EMAIL = #{email} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
AND T.TASK_STATE_CD = #{taskState}
AND T.TASK_NM LIKE CONCAT('%', #{taskNm}, '%')
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
AND TE.TASK_EMP_CD = #{taskEmpCd}
AND T.CHILD_TASK_ADD_YN = 'N'
AND (T.CHILD_TASK_ADD_YN = 'Y' OR T.CHILD_TASK_ADD_YN IS NULL)
AND E2.EMP_NM LIKE REPLACE(CONCAT('%', #{taskEmpNm}, '%'), ' ','')
AND TL.LABEL_ID = #{labelId} AND TL.EMAIL = #{email}
) )
ORDER BY T.TASK_STATE_CD, CASE WHEN T.TASK_END_DT is NULL THEN '2' WHEN T.TASK_END_DT = '' THEN '1' ELSE '0' END, T.TASK_END_DT, T.TASK_IMPORTANCE_CD, COALESCE(T.PARENT_TASK_ID, T.TASK_ID), T.PARENT_TASK_ID IS NOT NULL, T.TASK_ID
LIMIT #{start}, #{length}

		SELECT 
			COUNT(DISTINCT T.TASK_ID)
		FROM
			TASK_MASTER T
			INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID)
			LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD)
			INNER JOIN COMPANY_MASTER C ON (C.DOMAIN_ID = E.DOMAIN_ID AND C.COMPANY_CD = E.COMPANY_CD)
			INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID)
 			INNER JOIN EMP_MASTER E2  ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD)
			LEFT JOIN TASK_LABEL TL ON (TL.TASK_ID = T.TASK_ID AND TL.DOMAIN_ID = T.DOMAIN_ID)

			T.DOMAIN_ID = #{domainId}
			AND TE.EMAIL = #{email}
			AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)

				AND T.TASK_STATE_CD = #{taskState}


				AND T.TASK_NM LIKE CONCAT('%', #{taskNm}, '%')


				AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')


				AND T.TASK_START_DT >= #{taskStartDt}


				AND T.TASK_END_DT  <= #{taskEndDt}


				AND TE.TASK_EMP_CD = #{taskEmpCd}




						AND T.CHILD_TASK_ADD_YN = 'N'


