				, TASK_PROGRESS


				, PARENT_TASK_ID


				, CHILD_TASK_ADD_YN


				, CALENDAR_EVENT_ID

                , TASK_TYPE_CD
		        , PROJECT_ID
				, DEL_YN
				, UPDATE_USR
				, UPDATE_DT
				, CREATE_USR
				, CREATE_DT
			)
			VALUES (
