SELECT
	CALENDAR_EVENT_ID
	, TASK_OWNER_MEMBER_ID
FROM TASK_MASTER
WHERE TASK_ID = #{taskId}
AND DOMAIN_ID = #{domainId}

SELECT
	T.TASK_STATE_CD
	, COUNT(*) AS COUNT
FROM TASK_MASTER T
INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID)
WHERE TE.EMAIL = #{email}
	AND T.DOMAIN_ID = #{domainId}
	AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)

	AND T.TASK_START_DT >= #{taskStartDt}


	AND T.TASK_END_DT  <= #{taskEndDt}

GROUP BY T.TASK_STATE_CD
ORDER BY T.TASK_STATE_CD

SELECT
	T.TASK_STATE_CD
	, TE.TASK_EMP_CD
	, COUNT(*) AS COUNT
FROM TASK_MASTER T
INNER JOIN TASK_EMP TE ON (TE.TASK_ID = T.TASK_ID AND TE.DOMAIN_ID = T.DOMAIN_ID)
WHERE TE.EMAIL = #{email}
	AND T.DOMAIN_ID = #{domainId}
	AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)

	AND T.TASK_START_DT >= #{taskStartDt}


	AND T.TASK_END_DT  <= #{taskEndDt}

GROUP BY T.TASK_STATE_CD, TE.TASK_EMP_CD
ORDER BY T.TASK_STATE_CD, TE.TASK_EMP_CD
